def pancake_sort(arr):
    if len(arr) == 1:
        return arr
    pivot = arr[len(arr) - 1]
    i = 0
    while arr[i] > pivot:
        i += 1
    if i != 0:
        arr[i], arr[len(arr) - 1] = arr[len(arr) - 1], arr[i]
    else:
        return arr
    j = 0
    while j < len(arr):
        if arr[j] == pivot:
            arr[j], arr[i] = arr[i], arr[j]
            i -= 1
        j += 1
    return arr

