def max_path_sum(triangle, m, n):
    # Base case
    if m == 1:
        return triangle[0][n-1]
    if n == 1:
        return max(triangle[0][m-1], triangle[1][m-1])

    # Recursive case
    max_sum = 0
    for i in range(1, n):
        max_sum = max(max_sum, triangle[m-1][i-1] + max_path_sum(triangle, m-1, i))
    return max_sum

